const row = $input.item.json;

// Clean website_canonical from website first.
// This prevents stale/incomplete sheet values like "yoursite.com"
// from overriding the real website path like "https://1inch.com/card".
const websiteCanonical = (row.website || row.website_canonical || '')
  .toLowerCase()
  .trim()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/$/, '');

// Generate a random password for the BD account
const password = Math.random().toString(36).slice(-8) + 'A1!';

// Build the clean listing object for Supabase insert
const listing = {
  listing_type: row.listing_type || 'Company',
  logo: row.logo || null,
  cover_photo: row.cover_photo || null,
  profile_photo: row.profile_photo || null,
  first_name: row.first_name || null,
  last_name: row.last_name || null,
  email: row.email || null,
  company: row.company || null,
  phone_number: row.phone_number || null,
  fax_number: row.fax_number || null,
  address1: row.address1 || null,
  address2: row.address2 || null,
  city: row.city || null,
  zip_code: row.zip_code || null,
  state_code: row.state_code || null,
  country_code: row.country_code || null,
  website: row.website || null,
  website_canonical: websiteCanonical,
  twitter: row.twitter || null,
  facebook: row.facebook || null,
  linkedin: row.linkedin || null,
  youtube: row.youtube || null,
  instagram: row.instagram || null,
  tiktok: row.tiktok || null,
  discord: row.discord || null,
  about_me: row.about_me || null,
  about_me_staging: row.about_me_staging || row.about_me || null,
  search_description: row.search_description || null,
  profession_name: row.profession_name || null,
  services: row.services || null,
  published: true,
  verified: false,
  source: 'manual',
  status: 'export_ready',
  import_batch_id: $('Read AI Complete Rows').item.json.import_batch_id || null,
  password
};

// Remove null and empty-string values to keep insert clean
Object.keys(listing).forEach(k => {
  if (listing[k] === null || listing[k] === '') delete listing[k];
});

// Always keep these fields
listing.published = true;
listing.verified = false;
listing.source = 'manual';
listing.status = 'export_ready';
listing.website_canonical = websiteCanonical;
listing.password = password;

return [{ json: { ...listing } }];

const mergeNode = $('Merge Category Results to Listing Data').first().json || {};
const createdListing = $('Create a row').first().json || {};
const prepareData = $('Prepare Listing Data').first().json || {};

const listingId =
  mergeNode.listing_id ||
  createdListing.id ||
  null;

const servicesRaw =
  mergeNode.listing?.services ||
  prepareData.services ||
  '';

if (!listingId) {
  throw new Error(
    'No listing_id available for category insert. Debug: ' +
    JSON.stringify({
      merge_listing_id: mergeNode.listing_id,
      created_listing_id: createdListing.id,
      website_canonical: prepareData.website_canonical
    })
  );
}

const categoryRows = [];

if (servicesRaw && servicesRaw.trim() !== '') {
  const pairs = servicesRaw
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);

  pairs.forEach((pair, index) => {
    const parts = pair.split('=>').map(s => s.trim());

    categoryRows.push({
      listing_id: listingId,
      sub_name: parts[0] || null,
      subsub_name: parts[1] || null,
      is_primary_top: index === 0
    });
  });
}

return categoryRows.map(row => ({ json: row }));

const bdResponse = $input.item.json;
const prev = $('Merge Category Results to Listing Data').item.json;

if (prev.skipped || bdResponse.skipped) {
  return [{ json: { skipped: true, reason: prev.reason || 'upstream skipped' } }];
}

const bdMemberId = bdResponse?.message?.user_id 
  || bdResponse?.message?.member_id 
  || bdResponse?.message?.id 
  || bdResponse?.id 
  || null;

return [{ json: {
  listing_id: String(prev.listing_id || ''),
  bd_member_id: bdMemberId ? String(bdMemberId) : null,
  row_number: Number(prev.row_number) || 0,
  website: String(prev.website || ''),
  website_canonical: String(prev.website_canonical || ''),
  bd_response: JSON.stringify(bdResponse).slice(0, 500)
} }];

const items = $input.all();

const publishedCount = items.filter(i => !i.json.skipped).length;
const skippedCount = items.filter(i => i.json.skipped).length;
const skippedReasons = items
  .filter(i => i.json.skipped && i.json.reason)
  .map(i => i.json.reason);

return [{ json: {
  publishedCount,
  skippedCount,
  skippedReasons: skippedReasons.join(' | '),
  completedAt: new Date().toISOString()
}}];

const items = $input.all();
const prepareData = $('Prepare Listing Data').first().json;
const createdListing = $('Create a row').first().json;

const listingId = createdListing?.id || null;

if (!listingId) {
   return [{
    json: {
      skipped: true,
      reason: 'no_listing_id',
      debug_get_created_listing: createdListing,
      debug_website_canonical: prepareData.website_canonical
    }
  }];
}

const categoryResult = items[0]?.json;
const topCategoryId = categoryResult?.id || null;

if (!topCategoryId) {
  return [{
    json: {
      skipped: true,
      reason: 'Top category not found',
      debug_category_result: categoryResult,
      debug_profession_name: prepareData.profession_name
    }
  }];
}

return [{
  json: {
    listing_id: String(listingId),
    password: String(prepareData.password || ''),
    row_number: Number($('Loop Over Items').first().json.row_number) || 0,
    website: String(prepareData.website || ''),
    website_canonical: String(prepareData.website_canonical || ''),
    top_category_id: String(topCategoryId),
    listing: {
      email: String(prepareData.email || ''),
      company: String(prepareData.company || ''),
      listing_type: String(prepareData.listing_type || 'Company'),
      logo: String(prepareData.logo || ''),
      website: String(prepareData.website || ''),
      twitter: String(prepareData.twitter || ''),
      facebook: String(prepareData.facebook || ''),
      linkedin: String(prepareData.linkedin || ''),
      youtube: String(prepareData.youtube || ''),
      instagram: String(prepareData.instagram || ''),
      tiktok: String(prepareData.tiktok || ''),
      discord: String(prepareData.discord || ''),
      city: String(prepareData.city || ''),
      state_code: String(prepareData.state_code || ''),
      country_code: String(prepareData.country_code || ''),
      profession_name: String(prepareData.profession_name || ''),
      services: String(prepareData.services || ''),
      search_description: String(prepareData.search_description || ''),
      about_me: String(prepareData.about_me || ''),
      password: String(prepareData.password || '')
    }
  }
}];

const prev = $input.item.json;
return { json: {
  ...prev,
  website_canonical: prev.website_canonical
}};

const prev = $input.item.json;
if (prev.error) {
  return [{ json: { skipped: true, reason: 'duplicate_blocked' } }];
}
const listingId = prev.id || null;
if (!listingId) {
  return [{ json: { skipped: true, reason: 'no_listing_id' } }];
}
return [{ json: {
  listing_id: String(listingId),
  row_number: Number($('Loop Over Items').item.json.row_number) || 0
} }];
